{
  "id": "V033",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "고객 의견의 반복 주제와 경향을 파악하려는 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 1,
      "reason": "경향 파악과 근거 의견 정리는 있으나, 이를 요약 자료로 만들어 회의에 활용한다는 행동은 없음."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "이번 주 고객 의견의 요구와 불편 주제가 대상임."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "이번 주 고객 의견이 입력 자료로 보존됨."
    },
    {
      "field": "output",
      "score": 1,
      "reason": "주제별 경향과 근거 의견은 있으나 회의용 요약 자료라는 산출물은 명시되지 않음."
    },
    {
      "field": "constraints",
      "score": 0,
      "reason": "개별 고객 답장 및 제품 개선 효과 예측 제외 조건이 모든 관점에서 빠짐."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능을 추가하지 않음."
    },
    {
      "field": "roles",
      "score": 1,
      "reason": "서비스 기획팀의 역할은 명시되지 않지만, 역할을 달리 배정하는 내용도 없음."
    }
  ],
  "issues": [
    {
      "type": "OMISSION",
      "source_quote": "요약 자료를 만들어 회의에 사용하고 싶습니다.",
      "view_quote": "",
      "reason": "회의에 사용할 요약 자료의 작성 및 활용이 모든 관점에서 누락됨."
    },
    {
      "type": "OMISSION",
      "source_quote": "개별 고객에게 답장을 보내거나 제품 개선의 효과를 예측하는 작업은 제외합니다.",
      "view_quote": "",
      "reason": "답장 및 효과 예측을 제외한다는 제약이 모든 관점에서 누락됨."
    }
  ],
  "permission_interpretation": "사람의 답장·승인을 AI가 수행한다고 보는 내용은 없음. 원문의 답장 제외 조건은 모든 관점에서 보존되지 않음."
}
